ValidationRule.errorConditionFormula:
IF( /* 放寬：系統管理員角色 或 Profile */ OR( $UserRole.Name = "System Administrator", $Profile.Name = "System Administrator" ), FALSE,
AND( /* 僅限角色名稱包含 CC */ CONTAINS($UserRole.Name, "CC"),
/* 狀態條件 */ ISPICKVAL(Status__c, "In Progress"), ISPICKVAL(Approval_Status__c, "New"),
/* 以下任一欄位被變更就擋下 */ OR( ISCHANGED(CED_Note__c), ISCHANGED(Passenger_Name__c), ISCHANGED(Ticket_No__c), ISCHANGED(PNR__c), ISCHANGED(X1st_Flight_Date__c), ISCHANGED(X1st_Flight_No__c), ISCHANGED(X2nd_Flight_Date__c), ISCHANGED(X2nd_Flight_No__c), ISCHANGED(X3rd_Flight_Date__c), ISCHANGED(X3rd_Flight_No__c), ISCHANGED(X4th_Flight_Date__c), ISCHANGED(X4th_Flight_No__c) ) ) )
